package dev.codex.lastzhelper;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.net.Uri;import android.widget.*;import java.util.*;import org.json.*;
public final class MainActivity extends Activity implements JobRunner.Listener {
 TextView status;EditText from,to,skipState,powerLimit;CheckBox dry;RadioGroup destination;boolean pendingBubble;final List<Button> runButtons=new ArrayList<>();
 void text(LinearLayout box,String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setPadding(0,12,0,8);box.addView(t);}
 EditText field(LinearLayout box,String label,int value){text(box,label,14);EditText e=new EditText(this);e.setSingleLine(true);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);e.setText(String.valueOf(value));box.addView(e);return e;}
 void button(LinearLayout box,String label,String mode){Button b=new Button(this);b.setText(label);box.addView(b);if(!mode.equals("stop"))runButtons.add(b);b.setOnClickListener(v->launch(mode));}
 void save(){int power=TruckRules.parsePowerLimit(powerLimit.getText().toString()),skip=TruckRules.parseSkipState(skipState.getText().toString()),start=Integer.parseInt(from.getText().toString()),end=Integer.parseInt(to.getText().toString());if(start<1||end<start||end>9999||end-start>100)throw new IllegalArgumentException("Check bounty states");getSharedPreferences("runs",0).edit().putInt("start",start).putInt("end",end).putInt("attackPowerM",power).putInt("skipTruckState",skip).putBoolean("dry",dry.isChecked()).putString("shareDestination",SharingControls.selected(destination)).apply();}
 String version(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "?";}}
 void launch(String mode){try{if(mode.equals("run-bot")||mode.equals("preview-bot")){BotRun.service(this,mode.equals("preview-bot"));moveTaskToBack(true);return;}if(mode.equals("stop")){startForegroundService(new Intent(this,HelperService.class).setAction("stop"));return;}save();startForegroundService(new Intent(this,HelperService.class).setAction(mode).putExtra("options",JobRunner.options(this).toString()));moveTaskToBack(true);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 void openFloating(){if(Settings.canDrawOverlays(this)){startForegroundService(new Intent(this,HelperService.class).setAction("bubble"));moveTaskToBack(true);}else{pendingBubble=true;startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}}
 void floating(){try{save();openFloating();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 public void onCreate(Bundle saved){super.onCreate(saved);ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(20,12,20,24);scroll.addView(box);
  text(box,"Last Z Helper "+version(),24);text(box,"Open the account you want and run from its floating panel. The helper stays in that window and stops if the window or character changes.",14);
  android.content.SharedPreferences p=getSharedPreferences("runs",0);text(box,"Share destination",18);destination=SharingControls.create(this,p.getString("shareDestination",ShareDestination.WORLD),false);box.addView(destination);
  text(box,"Trucks",20);button(box,"Share 2+ orange frags","truck-share-2");button(box,"Share 3+ orange frags","truck-share-3");button(box,"Share cargo combos","truck-share-cargo");button(box,"Attack 3+ on Gaarix","truck-attack");
  text(box,"Cargo combos: 4+ boxes, 1+ orange frag with 3+ boxes, 2+ orange frags with 2+ boxes, or 3+ orange frags. One Lv.3 module chest icon counts as one box. Group truck shares use the power limit; World truck shares allow any known power. Attack only runs on Gaarix. Sharing sends the truck tile with no added text.",14);
  powerLimit=field(box,"Power below (million) â€” Send / Attack",p.getInt("attackPowerM",440));skipState=field(box,"Skip state for World shares (0 = none)",p.getInt("skipTruckState",0));
  dry=new CheckBox(this);dry.setText("Preview only â€” no messages or attacks");dry.setChecked(p.getBoolean("dry",true));box.addView(dry);
  text(box,"Bounties",20);from=field(box,"Start state",p.getInt("start",17));to=field(box,"End state",p.getInt("end",64));button(box,"Share bounties","bounties-share");
  text(box,"Maintenance",20);button(box,"Run bot","run-bot");button(box,"Preview bot","preview-bot");Button rotation=new Button(this);rotation.setText("Accounts and features");box.addView(rotation);runButtons.add(rotation);rotation.setOnClickListener(v->{startForegroundService(new Intent(this,HelperService.class).setAction("hide"));startActivity(new Intent(this,RotationActivity.class));});
  button(box,"STOP","stop");Button floating=new Button(this);floating.setText("Show floating controls");box.addView(floating);floating.setOnClickListener(v->floating());
  status=new TextView(this);status.setTextIsSelectable(true);box.addView(status);setContentView(scroll);JobRunner.listeners.add(this);update(JobRunner.state,JobRunner.detail,JobRunner.busy);
  pendingBubble=saved!=null&&saved.getBoolean("pendingBubble",false);
  if(saved==null&&!Settings.canDrawOverlays(this))try{openFloating();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}
 }
 public void onSaveInstanceState(Bundle out){out.putBoolean("pendingBubble",pendingBubble);super.onSaveInstanceState(out);}
 public void onResume(){super.onResume();if(from!=null&&!JobRunner.busy){android.content.SharedPreferences p=getSharedPreferences("runs",0);from.setText(""+p.getInt("start",17));to.setText(""+p.getInt("end",64));powerLimit.setText(""+p.getInt("attackPowerM",440));skipState.setText(""+p.getInt("skipTruckState",0));dry.setChecked(p.getBoolean("dry",true));destination.check(ShareDestination.GROUP.equals(p.getString("shareDestination",ShareDestination.WORLD))?1:2);}if(Settings.canDrawOverlays(this)){pendingBubble=false;try{openFloating();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}}
 public void update(String state,String detail,boolean busy){status.setText(state+"\n"+detail);for(Button b:runButtons)b.setEnabled(!busy);for(EditText e:new EditText[]{from,to,skipState,powerLimit})e.setEnabled(!busy);dry.setEnabled(!busy);SharingControls.enabled(destination,!busy);}
 public void onDestroy(){JobRunner.listeners.remove(this);super.onDestroy();}
}
